// hooks/query/useDelete.ts
import { useMutation, useQueryClient, type QueryKey } from '@tanstack/react-query';
import type { UseDeleteParams } from './types/crud.type';

export function useDelete<TResponse = unknown>({
    service,
    invalidateKeys = [],
    onSuccessCallback,
}: UseDeleteParams<TResponse>) {
    const queryClient = useQueryClient();

    return useMutation({
        mutationFn: (id: string) => service(id),
        onSuccess: (data) => {
            invalidateKeys.forEach((key) => {
                queryClient.invalidateQueries({ queryKey: key });
            });

            onSuccessCallback?.(data);
        },
    });
}

// hooks/query/usePost.ts
import { useMutation, useQueryClient, type QueryKey } from '@tanstack/react-query';
import type { UsePostParams } from './types/crud.type';

export function usePost<TPayload, TResponse>({
  service,
  invalidateKeys = [],
  onSuccessCallback,
}: UsePostParams<TPayload, TResponse>) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: service,
    onSuccess: (data) => {
      invalidateKeys.forEach((key) => {
        queryClient.invalidateQueries({ queryKey: key });
      });

      onSuccessCallback?.(data);
    },
  });
}

import { useQuery, type QueryKey } from '@tanstack/react-query';
import type { UseReadParams } from './types/crud.type';

export function useRead<TResponse, TMapped = TResponse>({
    queryKey,
    service,
    mapData,
    enabled = true,
}: UseReadParams<TResponse, TMapped>) {
    return useQuery({
        queryKey,
        queryFn: service,
        enabled,
        select: (data) => (mapData ? mapData(data) : (data)),
    });
}

// hooks/query/useUpdate.ts
import { useMutation, useQueryClient, type QueryKey } from '@tanstack/react-query';
import type { UseUpdateParams, UpdatePayload } from './types/crud.type';

export function useUpdate<TBody, TResponse>({
  service,
  invalidateKeys = [],
  onSuccessCallback,
}: UseUpdateParams<TBody, TResponse>) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, payload }: UpdatePayload<TBody>) => service(id, payload),
    onSuccess: (data) => {
      invalidateKeys.forEach((key) => {
        queryClient.invalidateQueries({ queryKey: key });
      });

      onSuccessCallback?.(data);
    },
  });
}

