import { useState, useCallback, useEffect } from 'react';
import { getAgents, createAgent, deleteAgent } from './Agents.service';

export const useAgentApi = () => {
    const [agents, setAgents] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isCreating, setIsCreating] = useState(false);
    const [isDeleting, setIsDeleting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const fetchAgents = useCallback(async () => {
        try {
            setIsLoading(true);
            setError(null);
            const data = await getAgents();
            const mapped = (data || []).map((agent: any) => ({
                ...agent,
                id: agent.id || agent._id,
                role: agent.systemPrompt || "",
                totalTokens: agent.totalTokens || 0,
                totalCost: agent.totalCost || 0,
                lastRun: agent.lastRun || "Never",
            }));
            setAgents(mapped);
        } catch (err: any) {
            setError(err.message || "Failed to fetch agents");
        } finally {
            setIsLoading(false);
        }
    }, []);

    const mutateCreate = useCallback(async (payload: any) => {
        try {
            setIsCreating(true);
            setError(null);
            await createAgent(payload);
            await fetchAgents();
        } catch (err: any) {
            setError(err.message || "Failed to create agent");
            throw err;
        } finally {
            setIsCreating(false);
        }
    }, [fetchAgents]);

    const mutateDelete = useCallback(async (id: string) => {
        try {
            setIsDeleting(true);
            setError(null);
            await deleteAgent(id);
            await fetchAgents();
        } catch (err: any) {
            setError(err.message || "Failed to delete agent");
            throw err;
        } finally {
            setIsDeleting(false);
        }
    }, [fetchAgents]);

    useEffect(() => {
        fetchAgents();
    }, [fetchAgents]);

    return {
        agents,
        isLoading,
        isCreating,
        isDeleting,
        error,
        refetch: fetchAgents,
        mutateCreate,
        mutateDelete
    };
};

import { api, endpoints } from "../../../configs/app.config";

export const getAgents = async () => {
    const { data } = await api.get(endpoints.agents);
    return data;
};

export const createAgent = async (payload: any) => {
    const { data } = await api.post(endpoints.agentsCreate, payload);
    return data;
};

export const deleteAgent = async (id: string) => {
    const { data } = await api.delete(endpoints.agentsDelete(id));
    return data;
};

export const agentsById = async (id: string) => {
    const { data } = await api.get(endpoints.agentsById(id));
    return data;
};

export const agentsUpdate = async (id: string, payload: any) => {
    const { data } = await api.put(endpoints.agentsUpdate(id), payload);
    return data;
};

