import { useState, useMemo, useCallback } from "react";
import type { AgentFormData } from "../../../configs/types/hook.type";
import { initialForm } from "../../../assets/data";
import { useAgentApi } from "./AgentApi";

export const useAgentsRead = () => {
    const { agents, isLoading, error, refetch } = useAgentApi();
    return { data: agents, isLoading, error, refetch };
};

export const useAgentPage = (api: any) => {
    const [showForm, setShowForm] = useState(false);
    const [formData, setFormData] = useState<AgentFormData>(initialForm);

    const resetForm = useCallback(() => {
        setFormData(initialForm);
    }, []);

    const handleSubmit = useCallback(
        async (e: React.FormEvent) => {
            e.preventDefault();
            if (!formData.name.trim() || !formData.role.trim()) return;

            const { role, ...rest } = formData;
            const backendData = {
                ...rest,
                systemPrompt: role,
                status: "active",
            };

            try {
                await api.mutateCreate(backendData);
                setShowForm(false);
                resetForm();
            } catch (err: any) {
                console.error(err);
            }
        },
        [formData, resetForm, api.mutateCreate],
    );

    const handleDeleteAgent = useCallback(
        async (id: string) => {
            try {
                await api.mutateDelete(id);
            } catch (err: any) {
                console.error(err);
            }
        },
        [api.mutateDelete],
    );

    const loading = api.isLoading || api.isCreating || api.isDeleting;
    const error = api.error;

    return useMemo(
        () => ({
            agentsData: {
                showForm,
                setShowForm,
                formData,
                setFormData,
                handleSubmit,
                deleteAgent: handleDeleteAgent,
                agents: api.agents,
                loading,
                error,
                refetchAgents: api.refetch,
            },
        }),
        [
            showForm,
            formData,
            handleSubmit,
            handleDeleteAgent,
            api.agents,
            loading,
            error,
            api.refetch,
        ],
    );
};

