import { useMemo } from 'react'

const dashboardCalculations = ({
    agents,
    tasks,
    selectedAgentId,
    selectedTaskId,
    search,
}: {
    agents: any[];
    tasks: any[];
    selectedAgentId: string;
    selectedTaskId: string;
    search: string;
}) => {
    const selectedAgent = useMemo(() => {
        return agents.find((a: any) => (a.id || a._id) === selectedAgentId) ?? agents[0] ?? null;
    }, [agents, selectedAgentId]);

    const selectedTask = useMemo(() => {
        return tasks.find((t: any) => (t.id || t._id) === selectedTaskId) ?? tasks[0] ?? null;
    }, [tasks, selectedTaskId]);

    const filteredTasks = useMemo(() => {
        const q = search.toLowerCase().trim();
        if (!q) return tasks;

        return tasks.filter((task: any) => {
            const agent = agents.find((a: any) => (a.id || a._id) === task.agentId);
            return (
                task.title.toLowerCase().includes(q) ||
                (task.input || "").toLowerCase().includes(q) ||
                (agent?.name || "").toLowerCase().includes(q)
            );
        });
    }, [search, tasks, agents]);

    const totalTokens = useMemo(
        () => tasks.reduce((sum: number, task: any) => sum + (task.totalTokens || 0), 0),
        [tasks],
    );

    const totalCost = useMemo(
        () => tasks.reduce((sum: number, task: any) => sum + (task.estimatedCost || 0), 0),
        [tasks],
    );

    const completedTasks = useMemo(
        () => tasks.filter((t: any) => t.status === "completed").length,
        [tasks],
    );

    const runningTasks = useMemo(
        () => tasks.filter((t: any) => t.status === "running").length,
        [tasks],
    );

    return (
        { selectedAgent, selectedTask, filteredTasks, totalTokens, totalCost, completedTasks, runningTasks }
    )
}

export default dashboardCalculations

import { useCallback, useEffect, useState } from 'react'
import { getTasks, runTask } from './Dashboard.service'

const useDashboardApi = () => {
    const [tasks, setTasks] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchData = useCallback(async () => {
        try {
            setIsLoading(true);
            setError(null);
            const tasksData = await getTasks();
            const mappedTasks = (tasksData || []).map((t: any) => ({
                ...t,
                id: t.id || t._id,
            }));
            setTasks(mappedTasks);
        } catch (err: any) {
            setError(err.message || "Failed to fetch dashboard data");
        } finally {
            setIsLoading(false);
        }
    }, []);
    
    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const handleRunTask = useCallback(
        async (taskId: string) => {
            try {
                setTasks((prev) =>
                    prev.map((t) =>
                        (t.id || t._id) === taskId ? { ...t, status: "running" } : t,
                    ),
                );
                await runTask(taskId);
                await fetchData();
            } catch (err: any) {
                setError(err.message || "Failed to run task");
            }
        },
        [fetchData],
    );
    return (
        {
            tasks,
            isLoading,
            error,
            fetchData,
            handleRunTask
        }
    )
}

export default useDashboardApi

