import { useEffect, useMemo, useState } from "react";
import dashboardCalculations from "./dashboardCalculations";

export const useDashboardLogic = (agents: any[] = [], sharedTasksApi: any = null) => {
  const [selectedAgentId, setSelectedAgentId] = useState<string>("");
  const [selectedTaskId, setSelectedTaskId] = useState<string>("");
  const [search, setSearch] = useState("");

  const [taskForm, setTaskForm] = useState({
    title: "",
    agentId: "",
    input: "",
  });

  const {
    tasks = [],
    isLoading,
    error,
    mutateRun: handleRunTask,
  } = sharedTasksApi || {
    tasks: [],
    isLoading: false,
    error: null,
    mutateRun: async () => {},
  };

  useEffect(() => {
    if (tasks.length > 0 && !selectedTaskId) {
      setSelectedTaskId(tasks[0].id || tasks[0]._id);
    }
  }, [tasks, selectedTaskId]);

  const {
    selectedAgent,
    selectedTask,
    filteredTasks,
    totalTokens,
    totalCost,
    completedTasks,
    runningTasks,
  } = dashboardCalculations({
    agents,
    tasks,
    selectedAgentId,
    selectedTaskId,
    search,
  });

  return useMemo(
    () => ({
      dashBoardData: {
        agents,
        tasks,
        taskForm,
        setTaskForm,
        selectedAgentId,
        setSelectedAgentId,
        selectedTaskId,
        setSelectedTaskId,
        selectedAgent,
        selectedTask,
        search,
        setSearch,
        filteredTasks,
        totalTokens,
        totalCost,
        completedTasks,
        runningTasks,
        loading: isLoading,
        error,
        runMockTask: handleRunTask,
      },
    }),
    [
      agents,
      tasks,
      taskForm,
      selectedAgentId,
      selectedTaskId,
      selectedAgent,
      selectedTask,
      search,
      filteredTasks,
      totalTokens,
      totalCost,
      completedTasks,
      runningTasks,
      isLoading,
      error,
      handleRunTask,
    ],
  );
};

