// src/module/Tasks/hook/useTasksLogic.ts
import { useCallback, useEffect, useMemo, useState } from "react";
import { initialTaskForm } from "../../../assets/data";
import type { TaskForm } from "../../../configs/types/hook.type";

export const useTasksLogic = (agents: any[] = [], sharedTasksApi: any = null) => {
    const {
        tasks = [],
        isLoading,
        isCreating,
        isRunning,
        error: apiError,
        mutateCreate,
        mutateRun,
    } = sharedTasksApi || {
        tasks: [],
        isLoading: false,
        isCreating: false,
        isRunning: false,
        error: null,
        mutateCreate: async () => {},
        mutateRun: async () => {},
    };

    const [taskForm, setTaskForm] = useState<TaskForm>(initialTaskForm);
    const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);

    useEffect(() => {
        if (agents.length > 0 && !taskForm.agentId) {
            setTaskForm((prev) => ({
                ...prev,
                agentId: agents[0].id,
            }));
        }
    }, [agents, taskForm.agentId]);

    const runRealTask = useCallback(
        async (taskId: string) => {
            try {
                await mutateRun(taskId);
            } catch (error) {
                console.error("Failed to run task:", error);
            }
        },
        [mutateRun],
    );

    const createRealTask = useCallback(async () => {
        if (!taskForm.title.trim() || !taskForm.input.trim()) return;

        const fallbackAgentId = agents[0]?.id ?? "";
        const payload = {
            title: taskForm.title,
            agentId: taskForm.agentId || fallbackAgentId,
            input: taskForm.input,
        };

        try {
            await mutateCreate(payload);

            setTaskForm({
                title: "",
                agentId: fallbackAgentId,
                input: "",
            });
        } catch (error) {
            console.error("Failed to create task:", error);
        }
    }, [taskForm, agents, mutateCreate]);

    const loading = isLoading || isCreating || isRunning;

    const error = apiError || null;

    const selectedTask = useMemo(
        () => tasks.find((t: any) => (t.id || t._id) === selectedTaskId) || null,
        [tasks, selectedTaskId],
    );

    return useMemo(
        () => ({
            taskData: {
                agents,
                tasks,
                taskForm,
                setTaskForm,
                runMockTask: runRealTask,
                createTask: createRealTask,
                loading,
                error,
                selectedTaskId,
                selectedTask,
                setSelectedTaskId,
            },
        }),
        [
            agents,
            tasks,
            taskForm,
            runRealTask,
            createRealTask,
            loading,
            error,
            selectedTaskId,
            selectedTask,
        ],
    );
};

import { useState, useCallback, useEffect } from 'react';
import { getTasks, createTask, runTask } from './Task.service';
import { mapTasks } from './tasks.mapper';

export const useTasksApi = () => {
    const [tasks, setTasks] = useState<any[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isCreating, setIsCreating] = useState(false);
    const [isRunning, setIsRunning] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const fetchData = useCallback(async () => {
        try {
            setIsLoading(true);
            setError(null);
            const tasksData = await getTasks();
            setTasks(mapTasks(tasksData));
        } catch (err: any) {
            setError(err.message || 'Failed to fetch tasks data');
        } finally {
            setIsLoading(false);
        }
    }, []);

    const mutateCreate = useCallback(async (payload: any) => {
        try {
            setIsCreating(true);
            setError(null);
            await createTask(payload);
            await fetchData();
        } catch (err: any) {
            setError(err.message || 'Failed to create task');
            throw err;
        } finally {
            setIsCreating(false);
        }
    }, [fetchData]);

    const mutateRun = useCallback(async (taskId: string) => {
        try {
            setIsRunning(true);
            setError(null);
            // Optimistic update
            setTasks(prev => prev.map(t => (t.id === taskId ? { ...t, status: 'running' } : t)));
            await runTask(taskId);
            await fetchData();
        } catch (err: any) {
            setError(err.message || 'Failed to run task');
            throw err;
        } finally {
            setIsRunning(false);
        }
    }, [fetchData]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    return {
        tasks,
        isLoading,
        isCreating,
        isRunning,
        error,
        refetch: fetchData,
        mutateCreate,
        mutateRun,
    };
};

