import { useMemo } from "react";

const useAgentUsageCalcuations = (tasks: any[], overview: any) => {
    const totalTokens = useMemo(() => {
        if (overview?.totalTokens != null) return overview.totalTokens;
        return tasks.reduce((sum: number, t: any) => sum + (t.totalTokens || 0), 0);
    }, [tasks, overview]);

    const totalCost = useMemo(() => {
        if (overview?.totalCost != null) return overview.totalCost;
        return tasks.reduce((sum: number, t: any) => sum + (t.estimatedCost || 0), 0);
    }, [tasks, overview]);

    const avgCostPerTask = useMemo(() => {
        if (overview?.avgCostPerTask != null) return overview.avgCostPerTask;
        return tasks.length > 0 ? totalCost / tasks.length : 0;
    }, [tasks, totalCost, overview]);
    return {
        totalTokens,
        totalCost,
        avgCostPerTask
    }
}

export default useAgentUsageCalcuations

import { useMemo } from "react";
import { useUsageOverview } from "./usage.service";
import useAgentUsageCalcuations from "./usage.Calculations";

export const useUsage = (agents: any[] = [], sharedTasksApi: any = null) => {
    const {
        tasks = [],
        isLoading: isTasksLoading,
        error: tasksError,
    } = sharedTasksApi || { tasks: [], isLoading: false, error: null };

    const {
        data: overview,
        isLoading: isOverviewLoading,
        error: overviewError,
    } = useUsageOverview();

    const { totalTokens, totalCost, avgCostPerTask } = useAgentUsageCalcuations(tasks, overview);

    const loading = isTasksLoading || isOverviewLoading;

    const error = tasksError || (overviewError as Error)?.message || null;

    return useMemo(
        () => ({
            usageData: {
                agents,
                tasks,
                totalTokens,
                totalCost,
                avgCostPerTask,
                loading,
                error,
            },
        }),
        [agents, tasks, totalTokens, totalCost, avgCostPerTask, loading, error],
    );
};

